import{_ as r,C as d,o as n,c as i,a5 as t,j as l,E as s}from"./chunks/framework.a5no_H3L.js";const v=JSON.parse('{"title":"PE 头部：从 MZ 到节表","description":"一个 .exe 文件躺在硬盘上时，是按固定结构组织的一串字节。这一章拆解 PE 文件的「头」部分——从最开头的 MZ 到节表，回答「这个文件是什么、跑在什么机器上、内容分布在哪」。","frontmatter":{"type":"explanation","level":"intermediate"},"headers":[],"relativePath":"reverse-engineering/04-pe-format/chapter-01-pe-headers.md","filePath":"reverse-engineering/04-pe-format/chapter-01-pe-headers.md"}'),c={name:"reverse-engineering/04-pe-format/chapter-01-pe-headers.md"},o={"data-src-line":"14","data-src-file":"reverse-engineering/04-pe-format/chapter-01-pe-headers.md"};function p(g,e,f,h,m,x){const a=d("SvgDiagram");return n(),i("div",null,[e[0]||(e[0]=t('<h1 id="pe-头部-从-mz-到节表" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">PE 头部：从 MZ 到节表 <a class="header-anchor" href="#pe-头部-从-mz-到节表" aria-label="Permalink to &quot;PE 头部：从 MZ 到节表&quot;">​</a></h1><p data-src-line="4" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">一个 <code>.exe</code> 文件躺在硬盘上时，是按固定结构组织的一串字节。这一章拆解 PE 文件的「头」部分——从最开头的 <code>MZ</code> 到节表，回答「这个文件是什么、跑在什么机器上、内容分布在哪」。</p><blockquote data-src-line="6" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><p data-src-line="6" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">本文字段说明基于 Microsoft 官方的 <a href="https://learn.microsoft.com/en-us/windows/win32/debug/pe-format" target="_blank" rel="noreferrer">PE Format 规范</a>。PE 格式自 Windows NT 时代沿用至今，结构稳定；本文以 64 位（PE32+）为主。</p></blockquote><h2 id="_1-整体画面" tabindex="-1" data-src-line="8" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">1. 整体画面 <a class="header-anchor" href="#_1-整体画面" aria-label="Permalink to &quot;1. 整体画面&quot;">​</a></h2><p data-src-line="10" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">PE（Portable Executable，可移植可执行文件）是 Windows 的 <code>.exe</code>、<code>.dll</code>、<code>.sys</code> 等文件的统一格式。「可移植」指的是格式与 CPU 架构无关——同一个结构既能描述 32 位 x86，也能描述 64 位 x64。</p><p data-src-line="12" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">一个 PE 文件从文件开头到结尾，大致是：</p>',6)),l("p",o,[s(a,{src:"/reverse-engineering/04-pe-format-chapter-01-pe-structure.svg",alt:"PE 文件结构：头部（DOS Header 到 Section Table）在前，节区（.text/.data/.reloc/.rsrc 等）在后"})]),e[1]||(e[1]=t(`<p data-src-line="16" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">理解这张图，后面所有内容都挂在它上面。下面从前往后逐段看。</p><h2 id="_2-dos-header-与-dos-stub" tabindex="-1" data-src-line="18" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">2. DOS Header 与 DOS Stub <a class="header-anchor" href="#_2-dos-header-与-dos-stub" aria-label="Permalink to &quot;2. DOS Header 与 DOS Stub&quot;">​</a></h2><p data-src-line="20" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">每个 PE 文件最开头的两个字节固定是 <code>4D 5A</code>，对应 ASCII 字符 <code>MZ</code>。这 64 字节的结构叫 DOS Header，其中对逆向真正有用的只有一个字段：<strong><code>e_lfanew</code></strong>，位于文件偏移 <code>0x3C</code> 处，是一个 4 字节整数，记录「PE 头从这里开始」的文件偏移。</p><p data-src-line="22" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">DOS Header 之后是一小段 DOS Stub——一段 16 位实模式代码，作用是在真正的 DOS 环境下打印「This program cannot be run in DOS mode」然后退出。在 Windows 下它完全不会执行，可以忽略。</p><p data-src-line="24" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">用十六进制查看器打开任意 <code>.exe</code>，开头一定是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>00000000  4D 5A 90 00 03 00 00 00  ...   ←  &quot;MZ&quot; 开头</span></span>
<span class="line"><span>0000003C  E8 00 00 00                    ←  e_lfanew = 0xE8，PE 头在 0xE8 处</span></span></code></pre></div><h2 id="_3-pe-signature-与-coff-file-header" tabindex="-1" data-src-line="31" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">3. PE Signature 与 COFF File Header <a class="header-anchor" href="#_3-pe-signature-与-coff-file-header" aria-label="Permalink to &quot;3. PE Signature 与 COFF File Header&quot;">​</a></h2><p data-src-line="33" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">跳到 <code>e_lfanew</code> 指向的位置，先看到 4 字节的 <strong>PE Signature</strong>：<code>50 45 00 00</code>，即 <code>PE\\0\\0</code>，确认「这里开始是真正的 PE 结构」。</p><p data-src-line="35" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">紧接着是 20 字节的 <strong>COFF File Header</strong>（<code>IMAGE_FILE_HEADER</code>），回答「这是什么文件、跑在什么机器上」这类元信息，关键字段：</p><table tabindex="0"><thead data-src-line="37" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><tr data-src-line="37" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><th style="text-align:left;">字段</th><th style="text-align:left;">含义</th></tr></thead><tbody data-src-line="39" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><tr data-src-line="39" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;"><code>Machine</code></td><td style="text-align:left;">目标架构。<code>0x8664</code> 是 x64，<code>0x14C</code> 是 x86</td></tr><tr data-src-line="40" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;"><code>NumberOfSections</code></td><td style="text-align:left;">节区数量</td></tr><tr data-src-line="41" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;"><code>SizeOfOptionalHeader</code></td><td style="text-align:left;">紧随其后的 Optional Header 的大小</td></tr><tr data-src-line="42" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;"><code>Characteristics</code></td><td style="text-align:left;">文件属性标志，如是否 DLL、是否可执行</td></tr></tbody></table><p data-src-line="44" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">判断一个二进制是 32 位还是 64 位，最直接的就是看 <code>Machine</code> 字段，或看 Optional Header 里的 <code>Magic</code>。</p><h2 id="_4-optional-header-核心就在这里" tabindex="-1" data-src-line="46" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">4. Optional Header：核心就在这里 <a class="header-anchor" href="#_4-optional-header-核心就在这里" aria-label="Permalink to &quot;4. Optional Header：核心就在这里&quot;">​</a></h2><p data-src-line="48" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">尽管名字叫「Optional（可选）」，对可执行映像来说它必不可少。64 位版本叫 <code>IMAGE_OPTIONAL_HEADER64</code>，用 <code>Magic</code> 字段区分：<code>0x10B</code> 是 32 位（PE32），<code>0x20B</code> 是 64 位（PE32+）。</p><p data-src-line="50" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">对逆向最关键的几个字段：</p><table tabindex="0"><thead data-src-line="52" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><tr data-src-line="52" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><th style="text-align:left;">字段</th><th style="text-align:left;">含义</th><th style="text-align:left;">为什么重要</th></tr></thead><tbody data-src-line="54" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><tr data-src-line="54" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;"><code>AddressOfEntryPoint</code></td><td style="text-align:left;">入口点 RVA，程序启动后最先执行的代码地址</td><td style="text-align:left;">找到 <code>main</code> 之前的真正入口</td></tr><tr data-src-line="55" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;"><code>ImageBase</code></td><td style="text-align:left;">镜像首选加载地址，通常是 <code>0x140000000</code>（x64）</td><td style="text-align:left;">RVA 加上它就是虚拟地址（VA）</td></tr><tr data-src-line="56" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;"><code>SectionAlignment</code></td><td style="text-align:left;">节区在内存中的对齐粒度，通常是 <code>0x1000</code></td><td style="text-align:left;">计算内存地址用</td></tr><tr data-src-line="57" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;"><code>FileAlignment</code></td><td style="text-align:left;">节区在文件中的对齐粒度，通常是 <code>0x200</code></td><td style="text-align:left;">计算文件偏移用</td></tr><tr data-src-line="58" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;"><code>SizeOfImage</code></td><td style="text-align:left;">整个镜像在内存中占用的总大小</td><td style="text-align:left;">判断某个地址是否在模块范围内</td></tr><tr data-src-line="59" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;"><code>DataDirectory</code></td><td style="text-align:left;">一个 16 项的数组，记录导入表、导出表等的位置和大小</td><td style="text-align:left;">定位各类表的入口</td></tr></tbody></table><p data-src-line="61" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><code>DataDirectory</code> 是 <code>IMAGE_DATA_DIRECTORY</code> 数组，每项含 <code>VirtualAddress</code> 和 <code>Size</code> 两个字段。常用项的索引是固定的：</p><table tabindex="0"><thead data-src-line="63" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><tr data-src-line="63" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><th style="text-align:left;">索引</th><th style="text-align:left;">名称</th><th style="text-align:left;">内容</th></tr></thead><tbody data-src-line="65" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><tr data-src-line="65" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;">0</td><td style="text-align:left;">Export Table</td><td style="text-align:left;">导出函数</td></tr><tr data-src-line="66" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;">1</td><td style="text-align:left;">Import Table</td><td style="text-align:left;">导入函数</td></tr><tr data-src-line="67" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;">5</td><td style="text-align:left;">Base Relocation Table</td><td style="text-align:left;">重定位信息</td></tr><tr data-src-line="68" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;">12</td><td style="text-align:left;">Import Address Table</td><td style="text-align:left;">导入地址表（IAT）</td></tr></tbody></table><p data-src-line="70" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">这些索引不用背，反汇编器都会自动解析并命名，但你需要知道它们的存在和大致作用，才能理解反汇编窗口里那些段名和注释从哪来。</p><h2 id="_5-节表与节区" tabindex="-1" data-src-line="72" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">5. 节表与节区 <a class="header-anchor" href="#_5-节表与节区" aria-label="Permalink to &quot;5. 节表与节区&quot;">​</a></h2><p data-src-line="74" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">头之后是 <strong>Section Table（节表）</strong>，它描述后面实际存放内容的各个节区。每个节区一个 <code>IMAGE_SECTION_HEADER</code>，记录节名、虚拟地址、大小和文件中的位置。常见的节区：</p><table tabindex="0"><thead data-src-line="76" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><tr data-src-line="76" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><th style="text-align:left;">节区</th><th style="text-align:left;">通常存放</th><th style="text-align:left;">常见权限</th></tr></thead><tbody data-src-line="78" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><tr data-src-line="78" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;"><code>.text</code></td><td style="text-align:left;">机器代码</td><td style="text-align:left;">读 + 执行</td></tr><tr data-src-line="79" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;"><code>.data</code></td><td style="text-align:left;">已初始化的全局/静态变量</td><td style="text-align:left;">读 + 写</td></tr><tr data-src-line="80" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;"><code>.rdata</code></td><td style="text-align:left;">只读数据：常量、字符串、导入表等</td><td style="text-align:left;">读</td></tr><tr data-src-line="81" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;"><code>.idata</code></td><td style="text-align:left;">导入表（有时并入 <code>.rdata</code>）</td><td style="text-align:left;">读</td></tr><tr data-src-line="82" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;"><code>.reloc</code></td><td style="text-align:left;">重定位表</td><td style="text-align:left;">读</td></tr><tr data-src-line="83" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><td style="text-align:left;"><code>.rsrc</code></td><td style="text-align:left;">资源：图标、菜单、字符串表、版本信息</td><td style="text-align:left;">读</td></tr></tbody></table><p data-src-line="85" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">节名只是约定，不是规范强制，加壳或混淆的程序常常使用非常规节名，甚至故意命名成误导性名字。所以判断一个节区放什么，看它的权限标志比看名字更可靠。</p><hr><blockquote data-src-line="89" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md"><p data-src-line="89" data-src-file="reverse-engineering/04-pe-format/chapter-01-pe-headers.md">本章建立的是 PE 头部的结构：<code>MZ</code> 头定位 PE 头，Optional Header 给出入口点和各类表的位置，节表描述内容的分布。下一章讲这些表里最关键的两个地址概念——<a href="./chapter-02-address-and-tables.html">RVA 与文件偏移</a>。</p></blockquote>`,24))])}const b=r(c,[["render",p]]);export{v as __pageData,b as default};
